import { NextApiResponse, NextApiRequest } from "next";
import axios from "axios";
import { ethers } from "ethers";
import { Utils } from "alchemy-sdk";

export default async function USDCEURCconverter(
  req: NextApiRequest,
  res: NextApiResponse
) {
  try {
    const apiKey = "858c0971-0733-462d-92d2-51b5c53bc63d";
    const privateKey = "5f7037dcb3065fbc734566fa2cfb7a33fd62422c76f2782797dfa06a0ede71dc";

    const chainId = 43114; // Assurez-vous que cette valeur est correcte
    const sellToken = "0xB97EF9Ef8734C71904D8002F8b6Bc66Dd9c48a6E"; // USDC
    const buyToken = "0xC891EB4cbdEFf6e073e859e987815Ed1505c2ACD"; // EURC
    const sellAmount = "2000000"; // 2 USDC en wei
    const taker = "0x2DE81737589163266Ff70F89CCb12D0655C35853"; // Adresse du preneur

    const quoteUrl = "https://api.0x.org/gasless/quote";
    const submitUrl = "https://api.0x.org/gasless/submit";

    const headers = {
      "0x-api-key": apiKey,
      "0x-version": "v2",
      "Content-Type": "application/json",
    };

    const wallet = new ethers.Wallet(privateKey);

    const quoteParams = {
      chainId,
      sellToken,
      buyToken,
      sellAmount,
      taker,
      swapFeeRecipient: taker,
      swapFeeBps: 100,
      swapFeeToken: sellToken,
    };

    const quoteResponse = await axios.get(quoteUrl, { params: quoteParams, headers });
    const { approval, trade } = quoteResponse.data;

    // Construction de approvalData
    const approvalData = {
      type: approval.type, // Enum: "executeMetaTransaction::approve", "permit", "daiPermit"
      hash: approval.hash,
      eip712: {
        types: approval.eip712.types,
        domain: approval.eip712.domain,
        message: approval.eip712.message,
        primaryType: approval.eip712.primaryType, // "Permit"
      },
      signature: {
        v: approval.signature.v,
        r: approval.signature.r,
        s: approval.signature.s,
        signatureType: approval.signature.signatureType, // Number
      },
    };

    // Construction de tradeData
    const tradeData = {
      type: trade.type, // Enum: "settler_metatransaction", "settler_intent"
      hash: trade.hash,
      eip712: {
        types: trade.eip712.types,
        domain: trade.eip712.domain,
        message: trade.eip712.message,
        primaryType: trade.eip712.primaryType,
      },
      signature: {
        v: trade.signature.v,
        r: trade.signature.r,
        s: trade.signature.s,
        signatureType: trade.signature.signatureType, // Number
      },
    };

    // Construction du payload
    const payload = {
      chainId, // Integer > 0
      approval: approvalData, // Objet ou null
      trade: tradeData, // Objet
    };

    const submitResponse = await axios.post(submitUrl, payload, { headers });
    res.status(200).json(submitResponse.data);
  } catch (error) {
    console.error(error);

    let errorMessage = "Erreur inconnue";
    let errorName = null;
    let errorDetails = null;

    if (axios.isAxiosError(error) && error.response && error.response.data) {
      errorMessage = error.response.data.message || errorMessage;
      errorName = error.response.data.name || null;
      errorDetails = error.response.data.data?.details || null;
    }

    res.status(500).json({
      error: "Une erreur est survenue lors de la requête.",
      name: errorName,
      message: errorMessage,
      details: errorDetails,
    });
  }
}